24	 * call, not surgery on a growing monolith; {@code reset} is data-driven off {@link #DOMAIN_TABLES}.
25	 */
26	@Profile("harness")
27	@RestController
28	@RequestMapping("/__test__")
29	public class TestSupportController {
30	
31	    /**
32	     * Every domain table, cleared on reset. Order is irrelevant: referential integrity is lifted
33	     * for the truncate and {@code RESTART IDENTITY} resets each table's generator. Add a table here
34	     * when its schema arrives.
